<?php
namespace App\Models;
use App\Models\Concerns\HasUuid; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class DiscordGuild extends Model { use HasUuid; protected $fillable=['discord_id','name','icon','owner_discord_id','discord_bot_id','is_active','moderator_role_discord_id','log_channel_discord_id','report_channel_discord_id','report_notification_channel_discord_id','report_mention_role_discord_ids','moderation_config']; protected function casts(): array{return ['is_active'=>'boolean','report_mention_role_discord_ids'=>'array','moderation_config'=>'array'];} public function bot(): BelongsTo{return $this->belongsTo(DiscordBot::class,'discord_bot_id');} public function channels(): HasMany{return $this->hasMany(DiscordChannel::class);} public function roles(): HasMany{return $this->hasMany(DiscordRole::class);} public function members(): HasMany{return $this->hasMany(DiscordMember::class);} public function botAssignments(): HasMany{return $this->hasMany(BotGuildAssignment::class);} public function voiceSessions(): HasMany{return $this->hasMany(VoiceSession::class);} public function reports(): HasMany{return $this->hasMany(VoiceReport::class);} }
